const CATALOG = [
  ['Bench Press', 'Chest', 'flat bench, barbell bench, bench'],
  ['Incline Dumbbell Press', 'Chest', 'incline db press, incline dumbbell bench'],
  ['Incline Bench Press', 'Chest', 'incline barbell press'],
  ['Dumbbell Fly', 'Chest', 'db fly, flyes, chest fly'],
  ['Cable Fly', 'Chest', 'cable crossover, crossover, pec fly'],
  ['Push-up', 'Chest', 'pushups, push ups'],
  ['Dumbbell Row', 'Back', 'db row, one arm row, single arm row, jumble row'],
  ['Barbell Row', 'Back', 'bent over row, bb row'],
  ['Lat Pulldown', 'Back', 'pulldown, lat pull down'],
  ['Seated Cable Row', 'Back', 'cable row, low row'],
  ['Pull-up', 'Back', 'pullups, chin up, chin-ups'],
  ['Deadlift', 'Back', 'conventional deadlift, dead lift'],
  ['Overhead Press', 'Shoulders', 'ohp, military press, shoulder press'],
  ['Dumbbell Shoulder Press', 'Shoulders', 'db shoulder press, seated dumbbell press'],
  ['Lateral Raise', 'Shoulders', 'side raise, side lateral, lateral raises'],
  ['Rear Delt Fly', 'Shoulders', 'reverse fly, rear delt'],
  ['Barbell Curl', 'Biceps', 'bicep curl, bb curl, straight bar curl'],
  ['Dumbbell Curl', 'Biceps', 'db curl, alternate curl'],
  ['Hammer Curl', 'Biceps', 'hammer curls, neutral grip curl'],
  ['Preacher Curl', 'Biceps', 'ez bar preacher, preacher'],
  ['Tricep Pushdown', 'Triceps', 'cable pushdown, rope pushdown, pushdown'],
  ['Skull Crusher', 'Triceps', 'lying tricep extension, skullcrushers'],
  ['Overhead Tricep Extension', 'Triceps', 'overhead extension, french press'],
  ['Squat', 'Legs', 'back squat, barbell squat'],
  ['Leg Press', 'Legs', 'leg press machine'],
  ['Romanian Deadlift', 'Legs', 'rdl, stiff leg deadlift'],
  ['Leg Extension', 'Legs', 'quad extension'],
  ['Leg Curl', 'Legs', 'hamstring curl, lying leg curl'],
  ['Calf Raise', 'Legs', 'calves, standing calf raise'],
  ['Plank', 'Core', 'planks'],
  ['Cable Crunch', 'Core', 'crunches, ab crunch'],
].map((entry) => ({ name: entry[0], muscleGroup: entry[1], aliases: entry[2] }));

const toSet = (row) => ({
  id: row.id,
  exercise: row.exercise,
  muscleGroup: row.muscleGroup || 'Full Body',
  setNo: row.setNo,
  reps: row.reps,
  weight: row.weight,
  unit: row.unit || 'kg',
  dayFocus: row.dayFocus || null,
  createdAt: row.createdAt,
});
const sets = $input.all().map((item) => item.json).filter((row) => row.id).map(toSet);

const isNewToCatalog = (set, index, all) => !CATALOG.some((entry) => entry.name === set.exercise) && all.findIndex((other) => other.exercise === set.exercise) === index;
const exercises = CATALOG.concat(sets.filter(isNewToCatalog).map((set) => ({ name: set.exercise, muscleGroup: set.muscleGroup, aliases: '' })));

const exerciseOrder = sets.map((set) => set.exercise).filter((name, index, all) => all.indexOf(name) === index);
const describe = (name) => '- ' + name + ': ' + sets.filter((set) => set.exercise === name).map((set) => set.reps + 'x' + set.weight + set.unit).join(', ');
const lastSet = sets[sets.length - 1] || null;

const PENDING_MINUTES = 15;
const pendingRow = $('Load pending question').first().json;
const isFresh = (row) => Boolean(row && row.note) && $now.diff(DateTime.fromJSDate(new Date(row.updatedAt)), 'minutes').minutes < PENDING_MINUTES;
const pending = isFresh(pendingRow) ? { note: pendingRow.note, question: pendingRow.question } : null;
const spokenFocus = sets.map((set) => set.dayFocus).filter(Boolean).pop() || null;

return [{
  json: {
    sets,
    exercises,
    lastSet,
    spokenFocus,
    exerciseNames: exercises.map((exercise) => exercise.name).join(', '),
    catalogForPrompt: exercises.map((exercise) => exercise.name + ' [' + exercise.muscleGroup + ']' + (exercise.aliases ? ' aka ' + exercise.aliases : '')).join('\n'),
    sessionSummary: sets.length ? exerciseOrder.map(describe).join('\n') : 'Nothing logged yet today.',
    lastExercise: lastSet ? lastSet.exercise : 'none',
    pendingNote: pending ? pending.note : '',
    pendingForPrompt: pending ? 'Earlier note still waiting for an answer: "' + pending.note + '"\nYou asked: "' + pending.question + '"' : 'No earlier question is waiting.',
  },
}];

const PAGE_ID = '40b37eff-28d4-8132-91fd-cb1e3a010096';
const DAY_STARTS_AT_HOUR = 4;
const MUSCLE_GROUPS = ['Chest', 'Back', 'Shoulders', 'Biceps', 'Triceps', 'Legs', 'Core', 'Cardio', 'Full Body'];
const DEFAULT_HELP = 'I could not tell what to log. Try: "bench press, 10 reps at 50 kg".';

const ctx = $('Build context').first().json;
const message = $('On Telegram message').first().json.message;
const transcript = $('Use voice transcript').isExecuted ? $('Use voice transcript').first().json.text : $('Use typed text').first().json.text;
const sessionDate = $now.minus({ hours: DAY_STARTS_AT_HOUR }).toFormat('yyyy-MM-dd');
const dayPrefix = '📅 ' + DateTime.fromISO(sessionDate).toFormat('ccc, d LLL yyyy');

const escapeHtml = (value) => String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const hasNumber = (value) => value !== null && value !== undefined && value !== '' && !isNaN(Number(value));
const formatWeight = (set) => set.weight + ' ' + set.unit;
const formatSet = (set) => set.reps + ' × ' + formatWeight(set);
const setCount = (count) => count + (count === 1 ? ' set' : ' sets');
const unique = (values) => values.filter((value, index, all) => all.indexOf(value) === index);

const fence = String.fromCharCode(96).repeat(3);
const modelText = (raw) => {
  const parts = (raw.content && raw.content.parts) || [];
  return parts.map((part) => part.text || '').join('') || raw.text || raw.output || '';
};
const parseModelOutput = (raw) => {
  if (raw && raw.intent) return raw;
  const cleaned = String(modelText(raw || {})).split(fence + 'json').join('').split(fence).join('').trim();
  try {
    return JSON.parse(cleaned);
  } catch (error) {
    return { intent: 'unclear', question: null };
  }
};

const normalize = (value) => String(value || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const matchesName = (exercise, name) => [exercise.name].concat(String(exercise.aliases || '').split(',')).some((candidate) => normalize(candidate) === normalize(name));
const validMuscle = (value) => (MUSCLE_GROUPS.includes(value) ? value : null);
const isValidSet = (set) => Boolean(set && set.exercise) && Number(set.reps) > 0 && hasNumber(set.weight) && Number(set.weight) >= 0;

const dayLabel = (sets, focus) => {
  const setsPerMuscle = {};
  sets.forEach((set) => {
    setsPerMuscle[set.muscleGroup] = (setsPerMuscle[set.muscleGroup] || 0) + 1;
  });
  const ranked = Object.keys(setsPerMuscle).sort((a, b) => setsPerMuscle[b] - setsPerMuscle[a]);
  const lead = focus || ranked[0];
  if (!lead) return '';
  return [lead + ' Day'].concat(ranked.filter((muscle) => muscle !== lead)).join(' + ');
};

const text = (content) => ({ type: 'text', text: { content: String(content) } });
const tableRow = (cells) => ({ object: 'block', type: 'table_row', table_row: { cells: cells.map((cell) => [text(cell)]) } });
const exerciseBlock = (name, sets) => ({
  object: 'block',
  type: 'heading_3',
  heading_3: {
    rich_text: [text(name + ' · ' + setCount(sets.length))],
    is_toggleable: true,
    children: [{
      object: 'block',
      type: 'table',
      table: {
        table_width: 3,
        has_column_header: true,
        has_row_header: false,
        children: [tableRow(['Set', 'Reps', 'Weight'])].concat(sets.map((set, index) => tableRow([index + 1, set.reps, formatWeight(set)]))),
      },
    }],
  },
});
const emptyDayBlock = { object: 'block', type: 'paragraph', paragraph: { rich_text: [text('No sets logged.')] } };

const renderDay = (sets, focus) => {
  const exercises = unique(sets.map((set) => set.exercise));
  const label = dayLabel(sets, focus);
  return {
    pageId: PAGE_ID,
    dayPrefix,
    dayTitle: label ? dayPrefix + ' · ' + label : dayPrefix,
    dayChildren: exercises.length ? exercises.map((name) => exerciseBlock(name, sets.filter((set) => set.exercise === name))) : [emptyDayBlock],
  };
};

const output = (route, reply, extra) => [{ json: Object.assign({ route, reply: escapeHtml(reply) }, extra || {}) }];
const replyOnly = (reply) => output('reply', reply);

const exerciseFor = (set) => {
  const known = ctx.exercises.find((exercise) => matchesName(exercise, set.exercise));
  if (known) return known;
  return { name: String(set.exercise).trim(), muscleGroup: validMuscle(set.muscle_group) || 'Full Body' };
};

const noteSoFar = ctx.pendingNote ? ctx.pendingNote + ' / then: ' + transcript : transcript;
const planUnclear = (parsed) => output('reply', (parsed && parsed.question) || DEFAULT_HELP, { awaitingAnswer: true, noteSoFar });

const planLogSets = (parsed) => {
  const spoken = validMuscle(parsed.day_focus);
  const focus = spoken || ctx.spokenFocus;
  const valid = (parsed.sets || []).filter(isValidSet);
  if (!valid.length) return spoken ? replyOnly('Noted: ' + spoken + ' Day. Send your first set.') : planUnclear(parsed);
  const allSets = ctx.sets.slice();
  const newRows = valid.map((set) => {
    const exercise = exerciseFor(set);
    const row = {
      sessionDate,
      exercise: exercise.name,
      muscleGroup: exercise.muscleGroup,
      setNo: allSets.filter((existing) => existing.exercise === exercise.name).length + 1,
      reps: Number(set.reps),
      weight: Number(set.weight),
      unit: set.unit === 'lb' ? 'lb' : 'kg',
      dayFocus: spoken || '',
      transcript,
      telegramMessageId: message.message_id,
    };
    allSets.push(row);
    return row;
  });
  const day = renderDay(allSets, focus);
  const reply = newRows.map((row) => '✅ ' + row.exercise + ' · Set ' + row.setNo + ': ' + formatSet(row)).join('\n');
  return newRows.map((row) => ({ json: Object.assign({ route: 'log', reply: escapeHtml(reply), row }, day) }));
};

const planUndo = () => {
  const last = ctx.lastSet;
  if (!last) return replyOnly('Nothing logged today to undo.');
  const remaining = ctx.sets.filter((set) => set.id !== last.id);
  return output('undo', '↩️ Removed ' + last.exercise + ' · Set ' + last.setNo + ' (' + formatSet(last) + ')', Object.assign({ undoId: last.id }, renderDay(remaining, ctx.spokenFocus)));
};

const planCorrect = (parsed) => {
  const last = ctx.lastSet;
  if (!last) return replyOnly('Nothing logged today to correct.');
  const correction = parsed.correction || {};
  const fixed = Object.assign({}, last, {
    reps: hasNumber(correction.reps) && Number(correction.reps) > 0 ? Number(correction.reps) : last.reps,
    weight: hasNumber(correction.weight) ? Number(correction.weight) : last.weight,
    unit: correction.unit === 'kg' || correction.unit === 'lb' ? correction.unit : last.unit,
  });
  const sets = ctx.sets.map((set) => (set.id === fixed.id ? fixed : set));
  return output('correct', '✏️ ' + fixed.exercise + ' · Set ' + fixed.setNo + ' is now ' + formatSet(fixed), Object.assign({ correction: { id: fixed.id, reps: fixed.reps, weight: fixed.weight, unit: fixed.unit } }, renderDay(sets, ctx.spokenFocus)));
};

const planSummary = () => {
  if (!ctx.sets.length) return replyOnly('Nothing logged today yet.');
  const exercises = unique(ctx.sets.map((set) => set.exercise));
  const line = (name) => {
    const sets = ctx.sets.filter((set) => set.exercise === name);
    return name + ' (' + setCount(sets.length) + '): ' + sets.map(formatSet).join(', ');
  };
  const label = dayLabel(ctx.sets, ctx.spokenFocus);
  return replyOnly(['📋 ' + (label || 'Today')].concat(exercises.map(line)).join('\n'));
};

const handlers = {
  log_sets: planLogSets,
  undo_last: planUndo,
  correct_last: planCorrect,
  summary: planSummary,
  unclear: planUnclear,
};
const parsed = parseModelOutput($input.first().json);
return (handlers[parsed.intent] || planUnclear)(parsed);

